<?php
namespace App\Providers;
use App\Contracts\FaceProvider;use App\Services\Face\{FakeFaceProvider,PythonFaceProvider,RekognitionFaceProvider};use Aws\Rekognition\RekognitionClient;use Illuminate\Support\ServiceProvider;use InvalidArgumentException;
class FaceServiceProvider extends ServiceProvider{public function boot():void{\App\Models\MediaAsset::deleting(function($asset){$rows=\App\Models\IndexedFace::with('faceCollection')->where('media_asset_id',$asset->id)->get()->groupBy('face_collection_id')->map(fn($g)=>['collection'=>$g->first()->faceCollection->provider_collection_ref,'face_ids'=>$g->pluck('provider_face_ref')->all()])->values()->all();if($rows)\App\Jobs\RemoveIndexedFaces::dispatch($rows);});\App\Models\Group::deleting(function($group){if($c=\App\Models\FaceCollection::where('group_id',$group->id)->first())\App\Jobs\DeleteFaceCollection::dispatch($c->provider_collection_ref);});}public function register():void{$this->app->singleton(FaceProvider::class,function(){return match(config('face.provider')){'fake'=>new FakeFaceProvider(),'python'=>new PythonFaceProvider(),'rekognition'=>new RekognitionFaceProvider(new RekognitionClient(['version'=>'latest','region'=>config('face.rekognition_region'),'credentials'=>config('filesystems.disks.s3.key')?['key'=>config('filesystems.disks.s3.key'),'secret'=>config('filesystems.disks.s3.secret'),'token'=>config('filesystems.disks.s3.token')]:null])),default=>throw new InvalidArgumentException('Unsupported FACE_PROVIDER.')};});}}
